-- MOSL workbook inputs as database rows (generated by seed/build_mosl_db_rows.py; NOT applied).
-- Needs AB's OK. Same rows as out/mosl/db_inputs.json. Idempotent: running it twice adds nothing.
-- Adds: 12 sb_assumptions, 11 sb_parity_pins, 101 sb_disclosure_facts (extracted_by 'excel_seed', status 'staged'), broker_id 'MOSL'.
-- Changes no existing row. Facts 846-1135 (the reviewed filing facts) are not touched.
-- Until this runs, `run_live.py --db --broker MOSL` refuses with a clear message and `--broker all` still publishes
-- Angel One and Groww (warning only). mtf_nii_yield_carry is the labelled assumption read by switch m-f.

begin;

insert into public.sb_assumptions (broker_id, key, value, value_text, unit, source_ref, note)
select x.broker_id, x.key, x.value, x.value_text, x.unit, x.source_ref, x.note
from jsonb_to_recordset($json$[
{
"broker_id": "MOSL",
"key": "mtf_day_basis",
"value": 247,
"value_text": null,
"unit": "days",
"source_ref": "excel:MTF data (2)!X12 (literal in =W12*NII/247)",
"note": "FY26 had 247 trading days; the workbook applies it to every quarter"
},
{
"broker_id": "MOSL",
"key": "cash_key_alignment",
"value": null,
"value_text": "workbook_as_used",
"unit": null,
"source_ref": "excel:backtesting cash!I:K",
"note": "NSE + BSE turnover as the workbook uses it: two rows out of date alignment from 2025-06-09 (docs/MOSL_ADR_Methodology.md issue #5); kept in parity mode"
},
{
"broker_id": "MOSL",
"key": "rule_fo_share",
"value": null,
"value_text": "avg_last_2_quarters; carry",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!I35:I37",
"note": "Q1 FY27 = mean of the last two typed shares, then carried (cancels in the output)"
},
{
"broker_id": "MOSL",
"key": "rule_fo_rate",
"value": null,
"value_text": "carry_last_calibrated_quarter",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!L36:L37",
"note": "Q1 FY27 rate carried"
},
{
"broker_id": "MOSL",
"key": "rule_cash_take_rate",
"value": null,
"value_text": "carry_prior_quarter_ignoring_Q1FY27_reported",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!J52:J54",
"note": "Q1 FY27 = Q4 FY26 (typed 228 ignored), then carried; per quarter, not per day"
},
{
"broker_id": "MOSL",
"key": "rule_cash_delivery_ratio",
"value": null,
"value_text": "avg_last_3_quarters",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!H53:H54",
"note": "trailing 3 quarters (Q3 FY27 includes the Q2 estimate)"
},
{
"broker_id": "MOSL",
"key": "rule_cash_share",
"value": null,
"value_text": "carry_last_typed_quarter",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!E53:E54",
"note": "Q1 FY27 share carried"
},
{
"broker_id": "MOSL",
"key": "rule_comm_share",
"value": null,
"value_text": "avg_last_4_quarters",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!L62",
"note": "mean of the last four quarters"
},
{
"broker_id": "MOSL",
"key": "rule_comm_take_rate",
"value": null,
"value_text": "carry_last_calibrated_quarter",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!L74",
"note": "Q1 FY27 carried"
},
{
"broker_id": "MOSL",
"key": "rule_net_gross",
"value": null,
"value_text": "avg_Q4FY26_Q1FY27; fo_carry_to_Q3FY27",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!R112:S114",
"note": "Q2 FY27 = mean(Q4 FY26, Q1 FY27); F&O Q3 FY27 = Q2 FY27; cash and commodities have no Q3 FY27 ratio"
},
{
"broker_id": "MOSL",
"key": "rule_mtf",
"value": null,
"value_text": "carry_last_actual_quarter",
"unit": null,
"source_ref": "excel:Motilal Oswal assumptions!E15:F15",
"note": "share and NII carried from Q1 FY27"
},
{
"broker_id": "MOSL",
"key": "mtf_nii_yield_carry",
"value": 0.12938330773959208,
"value_text": null,
"unit": "fraction",
"source_ref": "excel:Motilal Oswal assumptions!F14 (typed Q1 FY27 yield; the workbook carries it to Q2 FY27 as F15 = F14)",
"note": "[SOURCE NEEDED: MOSL does not publish an MTF yield] The workbook's typed 12.94% (unrounded), carried to every quarter after the last typed yield (MOSL data book has no MTF NII or yield line; docs/MOSL_ADR_Methodology.md section 2b). Read by live switch m-f."
}
]$json$::jsonb)
  as x(broker_id text, key text, value numeric, value_text text, unit text, source_ref text, note text)
on conflict (broker_id, key) do nothing;

